package com.neuroavocado.weightoverlay;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.util.HotkeyListener;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * Simple, always-on, display-only overlay that shows the player's
 * current carried weight, pulled directly from {@link Client#getWeight()}.
 * <p>
 * No event subscriptions are needed: overlays are re-rendered every
 * client frame, so this reflects equipment/inventory changes as soon
 * as they happen in-game.
 */
public class WeightOverlay extends OverlayPanel
{
    private final Client client;
    private final WeightOverlayConfig config;

    // Visibility is independent of whether the plugin itself is enabled --
    // this just lets the hotkey blank the panel out without unregistering
    // the overlay entirely.
    private boolean visible = true;

    private final HotkeyListener toggleListener;

    @Inject
    private WeightOverlay(Client client, WeightOverlayConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPreferredSize(new Dimension(110, 20));

        this.toggleListener = new HotkeyListener(config::toggleKeybind)
        {
            @Override
            public void hotkeyPressed()
            {
                visible = !visible;
            }
        };
    }

    HotkeyListener getToggleListener()
    {
        return toggleListener;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        if (!visible)
        {
            return null;
        }

        int weight = client.getWeight();
        Color color = Color.WHITE;

        if (config.useColors())
        {
            if (weight < 0)
            {
                color = Color.CYAN;
            }
            else if (weight >= config.warningThreshold())
            {
                color = Color.RED;
            }
        }

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Weight:")
                .right(weight + " kg")
                .rightColor(color)
                .build());

        return super.render(graphics);
    }
}

package com.neuroavocado.weightoverlay;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.ModifierlessKeybind;

@ConfigGroup("weightoverlay")
public interface WeightOverlayConfig extends Config
{
	@ConfigItem(
			keyName = "useColors",
			name = "Use warning colors",
			description = "Color the weight text based on the thresholds below. If off, text is always plain white.",
			position = 1
	)
	default boolean useColors()
	{
		return true;
	}

	@ConfigItem(
			keyName = "warningThreshold",
			name = "Warning threshold (kg)",
			description = "Weight at or above this value turns the text red.",
			position = 2
	)
	default int warningThreshold()
	{
		return 50;
	}

	@ConfigItem(
			keyName = "toggleKeybind",
			name = "Toggle visibility hotkey",
			description = "Press this key to temporarily hide/show the overlay (e.g. for screenshots) without disabling the plugin.",
			position = 3
	)
	default Keybind toggleKeybind()
	{
		return new ModifierlessKeybind(java.awt.event.KeyEvent.VK_F9, 0);
	}
}

package com.neuroavocado.weightoverlay;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "Weight Overlay",
		description = "Displays your character's current carried weight on screen at all times",
		tags = {"weight", "overlay", "carry", "equipment", "inventory"}
)
public class WeightOverlayPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WeightOverlay weightOverlay;

	@Inject
	private KeyManager keyManager;

	@Provides
	WeightOverlayConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WeightOverlayConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(weightOverlay);
		keyManager.registerKeyListener(weightOverlay.getToggleListener());
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(weightOverlay);
		keyManager.unregisterKeyListener(weightOverlay.getToggleListener());
	}
}

package com.neuroavocado.weightoverlay;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class WeightOverlayPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(WeightOverlayPlugin.class);
		RuneLite.main(args);
	}
}
